<!doctype html>
<html lang="sw">
<head>
    <meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
    <title>Dashibodi ya Shemasi</title>
    <style>
        :root{--ink:#18213d;--green:#159b62;--pale:#f5f7fb;--line:#e3e9f2;--muted:#75829a}*{box-sizing:border-box}body{margin:0;background:var(--pale);font:14px system-ui;color:#26314a}.app{display:grid;grid-template-columns:240px 1fr;min-height:100vh}.side{padding:24px 14px;background:#fff;border-right:1px solid var(--line)}.brand{font-size:18px;font-weight:800;padding:5px 12px 26px;color:var(--ink)}.nav{display:block;width:100%;background:transparent;border:0;padding:11px 12px;border-radius:8px;text-align:left;color:#63708a;font-weight:650;cursor:pointer}.nav:hover,.nav.active{background:#e8fbf1;color:#13794d}.label{margin:20px 12px 7px;font-size:10px;font-weight:800;color:#9da7b9;letter-spacing:.08em}.main{max-width:1300px;width:100%;margin:auto;padding:0 30px 32px}.top{height:82px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line)}h1,h2,h3{color:var(--ink)}h1{font-size:21px;margin:4px 0}.eyebrow{font-size:10px;letter-spacing:.1em;font-weight:800;color:var(--green)}.user{display:flex;gap:10px;align-items:center}.avatar{width:38px;height:38px;display:grid;place-items:center;border-radius:50%;background:#e7f8ef;color:#13794d;font-weight:800;overflow:hidden}.avatar img{width:100%;height:100%;object-fit:cover}.logout{color:#69758c;text-decoration:none;font-weight:700}.panel{display:none;padding-top:25px}.panel.active{display:block}.card{background:#fff;border:1px solid var(--line);border-radius:12px;padding:20px;box-shadow:0 4px 16px #1d2a4708}.columns{display:grid;grid-template-columns:1fr 1fr;gap:18px}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:12px;text-align:left;border-bottom:1px solid var(--line)}.table th{font-size:11px;color:var(--muted)}input,textarea,select{width:100%;border:1px solid #d9e1ed;border-radius:8px;padding:10px;font:inherit;background:#fff}.button{border:0;border-radius:8px;background:var(--green);color:#fff;padding:10px 13px;font-weight:750;cursor:pointer}.muted{color:var(--muted)}.field-label{display:block;font-weight:700;margin:14px 0 6px}.notice{margin-top:18px;color:#13794d}.visitor-row{border:1px solid var(--line);border-radius:10px;padding:12px;margin-bottom:10px}.visitor-top{display:grid;grid-template-columns:1fr 1fr 160px auto;gap:8px}.transfer-details{display:none;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:10px;padding-top:10px;border-top:1px dashed var(--line)}.visitor-row.is-moved .transfer-details{display:grid}.full{grid-column:1/-1}.file-note{font-size:12px;color:var(--muted);margin:0}.remove-visitor{background:#fff;color:#c24141;border:1px solid #f2caca}@media(max-width:850px){.visitor-top,.transfer-details{grid-template-columns:1fr 1fr}.visitor-top .remove-visitor{grid-column:span 2}}@media(max-width:700px){.app{grid-template-columns:1fr}.side{display:flex;gap:4px;overflow:auto;padding:12px}.brand,.label{display:none}.nav{white-space:nowrap;width:auto}.main{padding:0 14px 25px}.columns,.visitor-top,.transfer-details{grid-template-columns:1fr}.visitor-top .remove-visitor{grid-column:auto}.logout{display:none}}
    </style>
</head>
<body><div class="app"><aside class="side"><div class="brand">KANISA | SHEMASI</div><button class="nav active" onclick="show('overview',this)">Dashibodi</button><div class="label">HUDUMA ZA SHEMASI</div><button class="nav" onclick="show('attendance',this)">Mahudhurio</button><button class="nav" onclick="show('announcements',this)">Matangazo</button></aside><main class="main"><header class="top"><div><div class="eyebrow">OFISI YA KANISA</div><h1>Dashibodi ya Shemasi</h1></div><div class="user"><div class="avatar">@if($user->avatar)<img src="{{ asset('storage/'.$user->avatar) }}">@else{{ strtoupper(substr($user->name,0,1)) }}@endif</div><div><strong>{{ $user->name }}</strong><br><small class="muted">Shemasi wa Kanisa</small></div><a class="logout" href="{{ route('logout') }}" onclick="event.preventDefault();document.getElementById('logout').submit()">Toka</a><form id="logout" method="post" action="{{ route('logout') }}">@csrf</form></div></header>@if(session('success'))<div class="card notice">✓ {{ session('success') }}</div>@endif
<section id="overview" class="panel active"><h2>Karibu, Shemasi</h2><p class="muted">Tumia dashibodi hii kurekodi mahudhurio na kufuatilia matangazo ya kanisa.</p><div class="columns"><div class="card"><h3>Mahudhurio ya karibuni</h3><p style="font-size:28px;color:var(--green);font-weight:800;margin:8px 0;">{{ $attendances->count() }}</p><span class="muted">Rekodi za mahudhurio zilizoonyeshwa</span></div><div class="card"><h3>Matangazo hai</h3><p style="font-size:28px;color:var(--green);font-weight:800;margin:8px 0;">{{ $announcements->count() }}</p><span class="muted">Matangazo yanayoonekana kwa sasa</span></div></div></section>
<section id="attendance" class="panel"><h2>Mahudhurio</h2><div class="columns"><div class="card"><h3>Rekodi mahudhurio</h3><form method="post" action="{{ route('church-office.attendance.store') }}" enctype="multipart/form-data">@csrf<label class="field-label">Tarehe</label><input type="date" name="service_date" value="{{ old('service_date', now()->format('Y-m-d')) }}" required><label class="field-label">Jina la ibada</label><input name="service_name" value="{{ old('service_name') }}" placeholder="Mfano: Ibada ya Jumapili" required><label class="field-label">Wageni</label><p class="muted">Ukichagua “Amehamia”, taarifa zake zote zitasajiliwa moja kwa moja kama mshirika.</p><div id="visitor-items">@foreach(old('visitors', [['name' => '', 'phone' => '', 'has_moved' => 0]]) as $index => $visitor)<div class="visitor-row {{ ($visitor['has_moved'] ?? 0) ? 'is-moved' : '' }}"><div class="visitor-top"><input name="visitors[{{ $index }}][name]" value="{{ $visitor['name'] ?? '' }}" placeholder="Jina la mgeni"><input name="visitors[{{ $index }}][phone]" value="{{ $visitor['phone'] ?? '' }}" placeholder="Namba ya simu"><select name="visitors[{{ $index }}][has_moved]" class="moved-select"><option value="0" @selected(($visitor['has_moved'] ?? 0) == 0)>Hajaamia</option><option value="1" @selected(($visitor['has_moved'] ?? 0) == 1)>Amehamia</option></select><button type="button" class="button remove-visitor">Ondoa</button></div><div class="transfer-details"><input name="visitors[{{ $index }}][origin_location]" value="{{ $visitor['origin_location'] ?? '' }}" placeholder="Alipotoka (eneo/mji)"><input name="visitors[{{ $index }}][current_location]" value="{{ $visitor['current_location'] ?? '' }}" placeholder="Alipofikia (eneo/mtaa)"><input name="visitors[{{ $index }}][previous_church_name]" value="{{ $visitor['previous_church_name'] ?? '' }}" placeholder="Jina la kanisa alilotoka"><input name="visitors[{{ $index }}][previous_church_location]" value="{{ $visitor['previous_church_location'] ?? '' }}" placeholder="Mahali pa kanisa alilotoka"><input name="visitors[{{ $index }}][previous_pastor_name]" value="{{ $visitor['previous_pastor_name'] ?? '' }}" placeholder="Jina la mchungaji alikotoka"><input name="visitors[{{ $index }}][previous_pastor_phone]" value="{{ $visitor['previous_pastor_phone'] ?? '' }}" placeholder="Simu ya mchungaji"><input name="visitors[{{ $index }}][service]" value="{{ $visitor['service'] ?? '' }}" placeholder="Huduma yake"><select name="visitors[{{ $index }}][marital_status]"><option value="">Status ya ndoa</option><option value="single" @selected(($visitor['marital_status'] ?? '') === 'single')>Sijaoa / Sijaolewa</option><option value="married" @selected(($visitor['marital_status'] ?? '') === 'married')>Nimeoa / Nimeolewa</option><option value="widowed" @selected(($visitor['marital_status'] ?? '') === 'widowed')>Mjane</option></select><div class="full"><label class="field-label" style="margin:0 0 6px">Barua ya utambulisho (si lazima)</label><input type="file" name="visitors[{{ $index }}][introduction_letter]" accept=".pdf,.jpg,.jpeg,.png"><p class="file-note">PDF, JPG au PNG; ukubwa usiozidi MB 5.</p></div></div></div>@endforeach</div><button type="button" id="add-visitor" class="button" style="background:#fff;color:#13794d;border:1px solid #9fd8b9;">+ Ongeza mgeni</button><label class="field-label">Wanaume</label><input type="number" min="0" name="male_count" value="{{ old('male_count', 0) }}" required><label class="field-label">Wanawake</label><input type="number" min="0" name="female_count" value="{{ old('female_count', 0) }}" required><label class="field-label">Watoto</label><input type="number" min="0" name="children_count" value="{{ old('children_count', 0) }}"><label class="field-label">Maelezo (si lazima)</label><textarea name="notes">{{ old('notes') }}</textarea><p></p><button class="button">Hifadhi mahudhurio</button></form></div><div class="card"><h3>Mahudhurio yaliyorekodiwa</h3><table class="table"><thead><tr><th>Ibada</th><th>Jumla</th><th>Tarehe</th></tr></thead><tbody>@forelse($attendances as $attendance)<tr><td>{{ $attendance->service_name }}</td><td>{{ $attendance->male_count + $attendance->female_count + $attendance->children_count }}</td><td>{{ $attendance->service_date->format('d/m/Y') }}</td></tr>@empty<tr><td colspan="3" class="muted">Hakuna mahudhurio yaliyorekodiwa.</td></tr>@endforelse</tbody></table><h3 style="margin-top:24px;">Wageni waliohamia</h3><div style="display:flex;gap:8px;align-items:end;margin-bottom:12px;"><label class="muted" style="display:grid;gap:5px;">Chagua tarehe ya ripoti<input id="visitor-report-date" type="date" value="{{ now()->format('Y-m-d') }}"></label><a href="#" class="button visitor-report-link" data-period="week">PDF ya wiki</a><a href="#" class="button visitor-report-link" data-period="month">PDF ya mwezi</a></div><table class="table"><thead><tr><th>Jina</th><th>Simu</th><th>Tarehe</th></tr></thead><tbody>@forelse($visitors as $visitor)<tr><td>{{ $visitor->name }}</td><td>{{ $visitor->phone ?: '-' }}</td><td>{{ $visitor->visit_date->format('d/m/Y') }}</td></tr>@empty<tr><td colspan="3" class="muted">Hakuna mgeni aliyehamia aliyerekodiwa.</td></tr>@endforelse</tbody></table></div></div></section>
<section id="announcements" class="panel"><h2>Matangazo ya Kanisa</h2><div class="card">@forelse($announcements as $announcement)<div style="padding:14px 0;border-bottom:1px solid var(--line);"><strong>{{ $announcement->title }}</strong><p class="muted" style="margin:6px 0 0;">{{ $announcement->content }}</p></div>@empty<p class="muted">Hakuna matangazo kwa sasa.</p>@endforelse</div></section>
</main></div><template id="visitor-template"><div class="visitor-row"><div class="visitor-top"><input placeholder="Jina la mgeni"><input placeholder="Namba ya simu"><select class="moved-select"><option value="0">Hajaamia</option><option value="1">Amehamia</option></select><button type="button" class="button remove-visitor">Ondoa</button></div><div class="transfer-details"><input placeholder="Alipotoka (eneo/mji)"><input placeholder="Alipofikia (eneo/mtaa)"><input placeholder="Jina la kanisa alilotoka"><input placeholder="Mahali pa kanisa alilotoka"><input placeholder="Jina la mchungaji alikotoka"><input placeholder="Simu ya mchungaji"><input placeholder="Huduma yake"><select><option value="">Status ya ndoa</option><option value="single">Sijaoa / Sijaolewa</option><option value="married">Nimeoa / Nimeolewa</option><option value="widowed">Mjane</option></select><div class="full"><label class="field-label" style="margin:0 0 6px">Barua ya utambulisho (si lazima)</label><input type="file" accept=".pdf,.jpg,.jpeg,.png"><p class="file-note">PDF, JPG au PNG; ukubwa usiozidi MB 5.</p></div></div></div></template><script>function show(id,button){document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.nav').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active');button.classList.add('active')}const visitorBox=document.getElementById('visitor-items'),template=document.getElementById('visitor-template');function refreshVisitors(){[...visitorBox.querySelectorAll('.visitor-row')].forEach((row,index)=>{const inputs=row.querySelectorAll('input'),selects=row.querySelectorAll('select');const names=['name','phone','origin_location','current_location','previous_church_name','previous_church_location','previous_pastor_name','previous_pastor_phone','service','introduction_letter'];inputs.forEach((input,i)=>input.name=`visitors[${index}][${names[i]}]`);selects[0].name=`visitors[${index}][has_moved]`;selects[1].name=`visitors[${index}][marital_status]`})}function toggleTransfer(row){row.classList.toggle('is-moved',row.querySelector('.moved-select').value==='1')}visitorBox.addEventListener('change',event=>{if(event.target.classList.contains('moved-select'))toggleTransfer(event.target.closest('.visitor-row'))});document.getElementById('add-visitor').addEventListener('click',()=>{const row=template.content.firstElementChild.cloneNode(true);visitorBox.append(row);refreshVisitors();row.querySelector('input').focus()});visitorBox.addEventListener('click',event=>{if(event.target.classList.contains('remove-visitor')&&visitorBox.children.length>1){event.target.closest('.visitor-row').remove();refreshVisitors()}});[...visitorBox.querySelectorAll('.visitor-row')].forEach(toggleTransfer);refreshVisitors();document.querySelectorAll('.visitor-report-link').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();const date=document.getElementById('visitor-report-date').value;window.open(`{{ route('church-office.visitors.report.pdf') }}?period=${link.dataset.period}&date=${encodeURIComponent(date)}`,'_blank')}));</script></body></html>
